import type { FC } from 'react';
import { Download, Combine } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';

interface ConversionResultProps {
  fileCount: number;
  pdfBlob: Blob | null;
  fileName: string;
  progress: { index: number; total: number } | null;
  error: string | null;
  canGenerate: boolean;
  onGenerate: () => void;
}

// Generation is explicit (a button), not reactive to every add/remove/reorder/range
// edit — merging re-copies every selected page, which isn't cheap, so it only runs
// once the user is done arranging files and asks for it.
const ConversionResult: FC<ConversionResultProps> = ({ fileCount, pdfBlob, fileName, progress, error, canGenerate, onGenerate }) => {
  const handleDownload = () => {
    if (!pdfBlob) return;
    const url = URL.createObjectURL(pdfBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (error) {
    return (
      <div className="glass-panel p-6 space-y-3">
        <p className="text-sm text-destructive" role="alert">
          {error}
        </p>
        <button
          type="button"
          onClick={onGenerate}
          disabled={!canGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <Combine className="w-4 h-4" />
          Try again
        </button>
      </div>
    );
  }

  if (progress) {
    const pct = Math.round((progress.index / progress.total) * 100);
    return (
      <div className="glass-panel p-6 space-y-3" role="status" aria-live="polite">
        <p className="text-sm text-muted-foreground">
          Merging file {progress.index} of {progress.total}…
        </p>
        <div className="h-1.5 rounded-full bg-border overflow-hidden">
          <div className="h-full bg-accent transition-all duration-200" style={{ width: `${pct}%` }} />
        </div>
      </div>
    );
  }

  if (fileCount < 2) return null;

  if (!pdfBlob) {
    return (
      <div className="glass-panel p-6 flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm text-muted-foreground">{fileCount} files ready — arrange the order above, then merge.</p>
        <button
          type="button"
          onClick={onGenerate}
          disabled={!canGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <Combine className="w-4 h-4" />
          Merge PDFs
        </button>
      </div>
    );
  }

  return (
    <div className="glass-panel hover:border-border p-4 md:p-6 flex items-center justify-between gap-4 flex-wrap">
      <p className="text-sm font-medium text-foreground">{formatBytes(pdfBlob.size)} PDF, merged from {fileCount} files</p>
      <button
        type="button"
        onClick={handleDownload}
        className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
      >
        <Download className="w-4 h-4" />
        Download PDF
      </button>
    </div>
  );
};

export default ConversionResult;
