import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { Trash2 } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import UploadBox from '@/components/tools/merge-pdf/UploadBox';
import FileList from '@/components/tools/merge-pdf/FileList';
import ConversionResult from '@/components/tools/merge-pdf/ConversionResult';
import { usePersistentState } from '@/hooks/usePersistentState';
import { parsePageRange } from '@/lib/pdf/convert';
import { mergePdfs, type MergeEntry, type MergeProgress, type Rotation } from '@/lib/pdf/merge';

const NEXT_ROTATION: Record<Rotation, Rotation> = { 0: 90, 90: 180, 180: 270, 270: 0 };

const MergePdf: FC = () => {
  const [entries, setEntries] = usePersistentState<MergeEntry[]>('merge-pdf:entries', []);

  const [pdfBlob, setPdfBlob] = useState<Blob | null>(null);
  const [progress, setProgress] = useState<MergeProgress | null>(null);
  const [error, setError] = useState<string | null>(null);

  // A generated PDF only reflects the file set/order/ranges/rotations at the
  // moment it was built — once any of that changes, drop the stale result so
  // the UI goes back to the "Merge PDFs" prompt instead of offering an
  // out-of-date download.
  useEffect(() => {
    setPdfBlob(null);
    setError(null);
  }, [entries]);

  const handleAdd = (files: File[]) => {
    const added: MergeEntry[] = files.map((file) => ({
      id: crypto.randomUUID(),
      file,
      pageCount: null,
      pageRange: '',
      rotation: 0,
    }));
    setEntries((prev) => [...prev, ...added]);
  };

  const handleRemove = (id: string) => setEntries((prev) => prev.filter((entry) => entry.id !== id));
  const handleClearAll = () => setEntries([]);

  const handlePageRangeChange = (id: string, value: string) => {
    setEntries((prev) => prev.map((entry) => (entry.id === id ? { ...entry, pageRange: value } : entry)));
  };

  const handleRotate = (id: string) => {
    setEntries((prev) => prev.map((entry) => (entry.id === id ? { ...entry, rotation: NEXT_ROTATION[entry.rotation] } : entry)));
  };

  const handlePageCountLoaded = (id: string, count: number) => {
    setEntries((prev) => prev.map((entry) => (entry.id === id ? { ...entry, pageCount: count } : entry)));
  };

  const hasInvalidRange = entries.some((entry) => {
    const trimmed = entry.pageRange.trim();
    if (trimmed === '' || entry.pageCount === null) return false;
    return parsePageRange(trimmed, entry.pageCount).length === 0;
  });
  const canGenerate = entries.length >= 2 && !hasInvalidRange;

  const handleGenerate = () => {
    if (!canGenerate) return;
    setError(null);
    setProgress({ index: 0, total: entries.length });

    mergePdfs(entries, setProgress)
      .then((blob) => {
        setPdfBlob(blob);
        setProgress(null);
      })
      .catch((err: Error) => {
        setError(err.message || "These PDFs couldn't be merged");
        setProgress(null);
      });
  };

  return (
    <ToolLayout
      title="Merge PDF"
      description="Combine multiple PDFs into one — reorder files, pick specific pages from each, and rotate as needed, entirely in your browser."
    >
      <div className="max-w-2xl space-y-6">
        {entries.length > 0 ? (
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <h2 className="text-sm font-medium text-muted-foreground">
              {entries.length} {entries.length === 1 ? 'file' : 'files'}
            </h2>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={handleClearAll}
                className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-full text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-accent/5 transition-colors"
              >
                <Trash2 className="w-4 h-4" />
                Delete all
              </button>
              <UploadBox compact count={entries.length} onAdd={handleAdd} />
            </div>
          </div>
        ) : (
          <UploadBox count={entries.length} onAdd={handleAdd} />
        )}

        {entries.length === 1 && (
          <p className="text-xs text-muted-foreground">Add at least one more PDF to merge.</p>
        )}

        <FileList
          entries={entries}
          onReorder={setEntries}
          onRemove={handleRemove}
          onPageRangeChange={handlePageRangeChange}
          onRotate={handleRotate}
          onPageCountLoaded={handlePageCountLoaded}
        />

        {entries.length > 0 && (
          <p className="text-xs text-muted-foreground leading-relaxed">
            Drag the handle to reorder files. Leave a file's page field blank to include all of its pages, or enter a range like
            "1-3, 5" to include only some.
          </p>
        )}

        <ConversionResult
          fileCount={entries.length}
          pdfBlob={pdfBlob}
          fileName="merged.pdf"
          progress={progress}
          error={error}
          canGenerate={canGenerate}
          onGenerate={handleGenerate}
        />
      </div>
    </ToolLayout>
  );
};

export default MergePdf;
