import type { FC } from 'react';
import { useEffect, useState } from 'react';
import {
  DndContext,
  type DragEndEvent,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  SortableContext,
  arrayMove,
  verticalListSortingStrategy,
  sortableKeyboardCoordinates,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { GripVertical, X, FileText, RotateCw, Eye } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { formatBytes } from '@/lib/image/convert';
import { getPdfPageCount, convertPdfToImages, parsePageRange } from '@/lib/pdf/convert';
import type { MergeEntry } from '@/lib/pdf/merge';
import PdfPreviewDialog from '@/components/tools/PdfPreviewDialog';

interface FileListProps {
  entries: MergeEntry[];
  onReorder: (entries: MergeEntry[]) => void;
  onRemove: (id: string) => void;
  onPageRangeChange: (id: string, value: string) => void;
  onRotate: (id: string) => void;
  onPageCountLoaded: (id: string, count: number) => void;
}

interface SortableRowProps {
  entry: MergeEntry;
  index: number;
  total: number;
  onRemove: () => void;
  onPageRangeChange: (value: string) => void;
  onRotate: () => void;
  onPageCountLoaded: (count: number) => void;
  onPreview: () => void;
}

const SortableRow: FC<SortableRowProps> = ({ entry, index, total, onRemove, onPageRangeChange, onRotate, onPageCountLoaded, onPreview }) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: entry.id });
  const [thumbUrl, setThumbUrl] = useState<string | null>(null);
  const [thumbFailed, setThumbFailed] = useState(false);

  // Page count and a page-1 thumbnail both require loading the PDF via
  // pdfjs — fetched once per file, not on every render, and reported back up
  // (page count) so the range field can validate against it.
  useEffect(() => {
    let ignore = false;
    let objectUrl: string | null = null;
    setThumbFailed(false);

    getPdfPageCount(entry.file)
      .then((count) => {
        if (!ignore) onPageCountLoaded(count);
      })
      .catch(() => {
        /* page count is a display/validation nicety — a failure here still lets the merge itself proceed */
      });

    convertPdfToImages(entry.file, { scale: 0.4, quality: 55, pages: [1] })
      .then((pages) => {
        if (ignore) return;
        const blob = pages[0]?.blob;
        if (!blob) {
          setThumbFailed(true);
          return;
        }
        objectUrl = URL.createObjectURL(blob);
        setThumbUrl(objectUrl);
      })
      .catch(() => {
        if (!ignore) setThumbFailed(true);
      });

    return () => {
      ignore = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entry.file]);

  const trimmedRange = entry.pageRange.trim();
  const isRangeInvalid = entry.pageCount !== null && trimmedRange !== '' && parsePageRange(trimmedRange, entry.pageCount).length === 0;

  return (
    <div className="space-y-1">
      <div
        ref={setNodeRef}
        style={{ transform: CSS.Transform.toString(transform), transition }}
        className={`glass-panel hover:border-border flex items-center gap-3 p-2.5 ${isDragging ? 'z-10 opacity-90' : ''}`}
      >
        <div
          {...attributes}
          {...listeners}
          aria-label={`Reorder ${entry.file.name}, file ${index + 1} of ${total}`}
          className="cursor-grab active:cursor-grabbing touch-none text-muted-foreground/50 hover:text-muted-foreground shrink-0 p-1"
        >
          <GripVertical className="w-4 h-4" />
        </div>

        {thumbUrl && !thumbFailed ? (
          <button
            type="button"
            onPointerDown={(e) => e.stopPropagation()}
            onClick={onPreview}
            aria-label={`Preview ${entry.file.name}`}
            title="Click to preview the full PDF"
            className="group relative w-10 h-12 rounded-md overflow-hidden border border-border bg-background/50 shrink-0"
          >
            <img src={thumbUrl} alt="" className="w-full h-full object-cover" />
            <span className="absolute inset-0 flex items-center justify-center bg-black/0 group-hover:bg-black/50 transition-colors">
              <Eye className="w-3.5 h-3.5 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
            </span>
          </button>
        ) : (
          <div className="w-10 h-12 rounded-md overflow-hidden border border-border bg-background/50 shrink-0 flex items-center justify-center">
            <FileText className="w-4 h-4 text-muted-foreground" />
          </div>
        )}

        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-foreground truncate">{entry.file.name}</p>
          <p className="text-xs text-muted-foreground">
            {formatBytes(entry.file.size)}
            {entry.pageCount !== null && ` · ${entry.pageCount} ${entry.pageCount === 1 ? 'page' : 'pages'}`}
          </p>
        </div>

        <div className="w-32 shrink-0">
          <Input
            type="text"
            value={entry.pageRange}
            onChange={(e) => onPageRangeChange(e.target.value)}
            placeholder="All pages"
            aria-label={`Pages to include from ${entry.file.name}`}
            className={`h-9 text-xs ${isRangeInvalid ? 'border-destructive focus-visible:ring-destructive' : ''}`}
          />
        </div>

        <button
          type="button"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={onRotate}
          aria-label={`Rotate ${entry.file.name}`}
          title={`Rotate (currently ${entry.rotation}°)`}
          className="shrink-0 p-2 rounded-md text-muted-foreground hover:text-accent hover:bg-accent/10 transition-colors"
        >
          <RotateCw className="w-4 h-4 transition-transform" style={{ transform: `rotate(${entry.rotation}deg)` }} />
        </button>

        <button
          type="button"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={onRemove}
          aria-label={`Remove ${entry.file.name}`}
          className="shrink-0 p-2 rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
        >
          <X className="w-4 h-4" />
        </button>
      </div>
      {isRangeInvalid && (
        <p className="text-xs text-destructive pl-14">No valid pages in that range — this file has {entry.pageCount} pages.</p>
      )}
    </div>
  );
};

// Vertical list (not a thumbnail grid, like image-to-pdf's) — each row needs
// room for a page-range field and rotate control alongside the thumbnail,
// which a compact square card can't fit.
const FileList: FC<FileListProps> = ({ entries, onReorder, onRemove, onPageRangeChange, onRotate, onPageCountLoaded }) => {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );
  // A single shared dialog (rather than one per row) previews whichever file
  // was clicked — set on click, cleared on close.
  const [previewEntry, setPreviewEntry] = useState<MergeEntry | null>(null);

  if (entries.length === 0) return null;

  const ids = entries.map((entry) => entry.id);

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const from = ids.indexOf(String(active.id));
    const to = ids.indexOf(String(over.id));
    if (from === -1 || to === -1) return;
    onReorder(arrayMove(entries, from, to));
  };

  return (
    <>
      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <SortableContext items={ids} strategy={verticalListSortingStrategy}>
          <div className="space-y-2">
            {entries.map((entry, index) => (
              <SortableRow
                key={entry.id}
                entry={entry}
                index={index}
                total={entries.length}
                onRemove={() => onRemove(entry.id)}
                onPageRangeChange={(value) => onPageRangeChange(entry.id, value)}
                onRotate={() => onRotate(entry.id)}
                onPageCountLoaded={(count) => onPageCountLoaded(entry.id, count)}
                onPreview={() => setPreviewEntry(entry)}
              />
            ))}
          </div>
        </SortableContext>
      </DndContext>

      <PdfPreviewDialog
        open={previewEntry !== null}
        file={previewEntry?.file ?? null}
        fileName={previewEntry?.file.name ?? ''}
        pageCount={previewEntry?.pageCount ?? null}
        onClose={() => setPreviewEntry(null)}
      />
    </>
  );
};

export default FileList;
