import { parsePageRange } from './convert';

// Above this, embedding every file's pages in the main thread starts to feel
// like it's hung the tab — reject early with a clear reason instead (mirrors
// the image-to-pdf and pdf-to-jpg limits).
export const MAX_MERGE_FILES = 30;
export const MAX_BYTES_PER_FILE = 60 * 1024 * 1024;

export type Rotation = 0 | 90 | 180 | 270;

// A stable id decouples a picked file's identity from both its array position
// (which changes on reorder) and its File's own fields (which collide if the
// same file gets added twice) — dnd-kit and React list keys both need
// identity that survives reordering. pageCount is filled in asynchronously
// right after a file is added (see MergePdf.tsx) so the page-range field can
// validate against it.
export interface MergeEntry {
  id: string;
  file: File;
  pageCount: number | null;
  /** Which of this file's pages to include, e.g. "1-3, 5" — blank means all pages. */
  pageRange: string;
  rotation: Rotation;
}

export interface MergeProgress {
  index: number;
  total: number;
}

/** Merges the given PDFs, in order, into one PDF — each entry contributes only the
 * pages selected by its pageRange (blank = all), rotated by its rotation. Built
 * entirely in memory in the browser, never uploaded anywhere. */
export async function mergePdfs(entries: MergeEntry[], onProgress?: (progress: MergeProgress) => void): Promise<Blob> {
  if (entries.length > MAX_MERGE_FILES) {
    throw new Error(`That's ${entries.length} files — the limit is ${MAX_MERGE_FILES} per merge.`);
  }

  // pdf-lib is ~400kB — imported dynamically so it's only downloaded once the
  // user actually generates a PDF, not just from visiting the page.
  const { PDFDocument, degrees } = await import('pdf-lib');
  const outDoc = await PDFDocument.create();

  for (let i = 0; i < entries.length; i++) {
    onProgress?.({ index: i + 1, total: entries.length });
    const entry = entries[i];

    const bytes = await entry.file.arrayBuffer();
    const srcDoc = await PDFDocument.load(bytes);
    const pageCount = srcDoc.getPageCount();

    const selected = entry.pageRange.trim() === '' ? Array.from({ length: pageCount }, (_, p) => p + 1) : parsePageRange(entry.pageRange, pageCount);
    if (selected.length === 0) continue;

    const copiedPages = await outDoc.copyPages(srcDoc, selected.map((p) => p - 1));
    for (const page of copiedPages) {
      if (entry.rotation !== 0) {
        page.setRotation(degrees((page.getRotation().angle + entry.rotation) % 360));
      }
      outDoc.addPage(page);
    }
  }

  if (outDoc.getPageCount() === 0) {
    throw new Error('Nothing to merge — check that each file has a valid page selection.');
  }

  const outBytes = await outDoc.save();
  return new Blob([outBytes], { type: 'application/pdf' });
}
